// Port of shadcn's app-sidebar.tsx.
//
// DEVIATION: our <Sidebar> registry part has no `variant`/`collapsible`
// props (see ui/sidebar/sidebar.marko) — source passes
// variant="inset" collapsible="offcanvas". "offcanvas" is this part's only
// behavior already; "inset" cannot be expressed (see page.marko's notes).
//
// Icons: tabler-icons SVGs are reproduced as raw inner-markup strings
// (mixed <rect>/<circle>/<path> children, so a single `d` string like
// sidebar-07/nav-main.marko uses isn't enough) and rendered through the
// `svgIcon` helper below with $!{} — a `<const>` cannot hold a multi-line
// tag expression directly (Marko's parser rejects a JSX-shaped value
// spanning lines inside `<const/x=() => <svg>...`).
import Sidebar from "../../components/ui/sidebar/sidebar.marko";
import SidebarHeader from "../../components/ui/sidebar/header.marko";
import SidebarContent from "../../components/ui/sidebar/content.marko";
import SidebarFooter from "../../components/ui/sidebar/footer.marko";
import SidebarMenu from "../../components/ui/sidebar/menu.marko";
import SidebarMenuItem from "../../components/ui/sidebar/menu-item.marko";
import SidebarMenuButton from "../../components/ui/sidebar/menu-button.marko";
import NavMain from "./nav-main.marko";
import NavDocuments from "./nav-documents.marko";
import NavSecondary from "./nav-secondary.marko";
import NavUser from "./nav-user.marko";

export interface Input {
  open?: boolean;
}

static const icons: Record<string, string> = {
